startGuideActionCreate: "Maak een aantal",
startGuideActionMenu: "Selecteer menu",
startGuideActivity: "Activiteiten zijn de taken gepland voor jouw projecten. <br/> Je kunt de werk uiteensplitsings-structuur van je projecten aanmaken. <br/> Er is geen limiet van de nivo's van deze structuur in fasen / sub-fasen / taken / subtaken ...",
startGuideAffectation: "Een resource mag worden beïnvloed in een project om de items te zien. <br/> Beïnvloeding van een project geeft automatisch zichtbaarheid aan de items en aan de sub-projecten.",
startGuideClient: "Klanten zijn de entiteiten waarvoor je werkt. <br/> Ze kunnen binnen of buiten je organisatie zijn.",
startGuideContact: "Contactpersonen zijn de personen waarmee je in contact staat binnen je klantenbestand.",
startGuideFooter: "Hier zijn de belangrijkste kenmerken <br/> Zodra je vertrouwd bent met deze functies zul je in staat zijn om de (vele) andere modules te ontdekken om je projecten te kunnen beheren.",
startGuideImputation: "Resources voeren hun werk uit op het werkverdeling scherm&#44; van dag tot dag en van activiteit tot activiteit. <br/>Herinschatting van het «resterende» werk maakt actualisering van de projectplanning mogelijk met echte vooruitgang.",
startGuideIntro: "Hier is hulp in het kort om uw eerste stappen met ProjeQtOr verlichten. <br> Volg deze stappen om de eerste elementen te configureren. <br> Aarzel niet om [F1] in te toetsen voor de gebruikshandleiding&#44; waar u meer hulp zult vinden. < br> Ga terug naar &#34;vandaag&#34; pagina om deze &#34;start gids&#34; pagina aan te treffen.",
startGuideMilestone: "Mijlpalen zijn de belangrijkste datums van projecten. <br/> Ze kunnen de binnenkomende (vaste mijlpalen) of vereiste resultaten (dynamische mijlpalen) definiëren.",
startGuidePlanning: "Planning stelt een Gantt-weergave voor. <br/> Om activiteiten te plannen moet je resources toe te wijzen aan activiteiten en het werk definiëren wat gedaan moet worden&#44; omdat de planningwerk gedreven is. <br/> Dan kan je relatie tussen taken (voorgaande schakels) en mijlpalen te definiëren. .. <br/> vervolgens kunt je de planningsberekening uitvoeren&#44; rekening houdend met alle beperkingen van de resources zoals beschikbaarheid.",
startGuideProject: "Project is het belangrijkste onderdeel in ProjeQtOr. <br/> Elk item is gekoppeld aan een project. <br/> Toegangsrechten worden ook vastgelegd op projectniveau.",
startGuideResource: "Resources zijn de personen die werken aan taken. <br/> Indien je «is een gebruiker» aanvinkt&#44; is deze resource in staat om verbinding te maken met ProjeQtOr.",
startGuideTicket: "Tickets stellen je in staat om iedere opvallende gebeurtenis gekoppeld aan het project te volgen&#44; zoals bugs of welk verzoek dan ook <br/> Zij kunnen gemakkelijk worden gekopieerd naar de activiteiten als dat nodig is&#44; zonder opnieuw de gegevens te moeten in voeren en blijven gekoppeld aan de oorspronkelijke aanvraag.",
startGuideTitle: "Start Gids",
startGuideUser: "Gebruikers zijn de personen die verbinding kan maken met de applicatie. <br/> Zij moeten een profiel hebben dat de toegangsrechten tot de onderdelen bepalen.",
